package it.frociart.app;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import static it.frociart.app.FlowModel.*;
public final class OutputImportRegressionTests {
 static int checks;static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static String text(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 static String run(Document d,String[] inputs){FlowEngine.Runner r=new FlowEngine.Runner(d);int at=0;for(int i=0;i<10000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){if(r.state==FlowEngine.State.WAITING){check(at<inputs.length,"Input available");r.submitInput(inputs[at++]);}else r.step();}check(r.state==FlowEngine.State.COMPLETED,"Completion: "+r.errorMessage);return String.join("|",r.output);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),out=root.resolve("import-android");Files.createDirectories(out);
  for(String row:Files.readAllLines(root.resolve("import-cases.tsv"),StandardCharsets.UTF_8)){String[] parts=row.split("\t",-1);Path source=root.resolve("import-fixtures/"+parts[0]+".fprg");String original=text(source);Document d=FlowgorithmImport.decode(original);String[] inputs=parts[2].isEmpty()?new String[0]:parts[2].split("\\|");check(run(d,inputs).equals(parts[1]),"Execution "+parts[0]);check(text(source).equals(original),"Original untouched");String encoded=FlowCodec.encode(d);check(!encoded.contains("PRIVATE_HISTORY_MARKER")&&!encoded.contains("PRIVATE_AUTHOR_MARKER"),"Metadata omitted");Files.write(out.resolve(parts[0]+".frociart"),encoded.getBytes(StandardCharsets.UTF_8));check(run(FlowCodec.decode(text(out.resolve(parts[0]+".frociart"))),inputs).equals(parts[1]),"Save/reopen "+parts[0]);check(run(FlowPseudocode.decode(FlowPseudocode.encode(d)),inputs).equals(parts[1]),"Pseudocode "+parts[0]);FlowAutoLayout.apply(d);check(run(d,inputs).equals(parts[1]),"Riordina "+parts[0]);Path pc=root.resolve("import-pc/"+parts[0]+".frociart");if(Files.exists(pc))check(run(FlowCodec.decode(text(pc)),inputs).equals(parts[1]),"Cross-platform file "+parts[0]);}
  try(DirectoryStream<Path> stream=Files.newDirectoryStream(root.resolve("import-fixtures"),"reject-*.fprg")){for(Path p:stream){boolean rejected=false;try{FlowgorithmImport.decode(text(p));}catch(IllegalArgumentException e){rejected=true;check(e.getMessage().contains("Flowgorithm"),"Localized diagnostic: "+p);}check(rejected,"Reject "+p);}}
  Document notes=FlowgorithmImport.decode(text(root.resolve("import-fixtures/notes.fprg")));boolean consecutive=false,trailing=false;for(Node n:notes.nodes){if("Prima nota\nSeconda nota".equals(n.comment))consecutive=true;if(n.kind==END)trailing=n.comment!=null&&n.comment.contains("Coda ramo")&&n.comment.contains("Coda ciclo");check(n.kind!=PROCESS,"No executable comment assignments");}check(consecutive&&trailing,"Comments preserved");System.out.println("FLOWGORITHM_ANDROID_CORE PASS checks="+checks);
 }
}
